package id.deathcount; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerPlayer; import net.fabricmc.fabric.api.event.lifecycle.v1.*; public class MockHarness {public static void main(String[] args){DeathCountMod mod=new DeathCountMod();mod.onInitialize();MinecraftServer worldA=new MinecraftServer();ServerPlayer pA=new ServerPlayer();pA.deaths=3;worldA.players.players.add(pA);ServerLifecycleEvents.SERVER_STARTED.fire(worldA);for(int i=0;i<22;i++) ServerTickEvents.END_SERVER_TICK.fire(worldA);require(pA.actionbars>0,"hud missing");require(pA.lastActionbar.contains("Death Count: 3"),"count read incorrect");require(worldA.cmds.stream().anyMatch(c->c.contains("summon minecraft:text_display")&&c.contains("Death Count: 3")),"floating label missing");int oldCommands=worldA.cmds.size();pA.deaths=4;for(int i=0;i<11;i++) ServerTickEvents.END_SERVER_TICK.fire(worldA);require(pA.lastActionbar.contains("Death Count: 4"),"updated death missing");ServerLifecycleEvents.SERVER_STOPPING.fire(worldA);MinecraftServer worldB=new MinecraftServer();ServerPlayer pB=new ServerPlayer();pB.deaths=0;worldB.players.players.add(pB);ServerLifecycleEvents.SERVER_STARTED.fire(worldB);for(int i=0;i<11;i++) ServerTickEvents.END_SERVER_TICK.fire(worldB);require(pB.lastActionbar.contains("Death Count: 0"),"new world not zero");ServerLifecycleEvents.SERVER_STOPPING.fire(worldB);System.out.println("PASS simulated world A 3→4; world B 0; red skull + floating label + actionbar; minecraft="+System.getProperty("mock.mc"));}static void require(boolean x,String s){if(!x)throw new AssertionError(s);}}